    <style>
      :root {
        color-scheme: light;
        --bg: #f5f1ea;
        --surface: #fffdf9;
        --surface-2: #f3ece2;
        --ink: #1f1a17;
        --muted: #6d635c;
        --line: rgba(31, 26, 23, 0.12);
        --brand: #9d4f2b;
        --brand-2: #0f766e;
        --accent: #d9a441;
        --shadow: 0 18px 50px rgba(47, 28, 12, 0.12);
        --radius-xl: 28px;
        --radius-lg: 22px;
        --radius-md: 16px;
        --container: 1180px;
      }

      * {
        box-sizing: border-box;
      }

      html {
        scroll-behavior: smooth;
      }

      body {
        margin: 0;
        font-family:
          Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
          "Segoe UI", sans-serif;
        background:
          radial-gradient(circle at top left, rgba(217, 164, 69, 0.15), transparent 28%),
          radial-gradient(circle at right 10% top 25%, rgba(15, 118, 110, 0.1), transparent 26%),
          var(--bg);
        color: var(--ink);
        line-height: 1.5;
      }

      img {
        display: block;
        max-width: 100%;
      }

      a {
        color: inherit;
        text-decoration: none;
      }

      .skip-link {
        position: absolute;
        left: 0.75rem;
        top: -3rem;
        z-index: 1000;
        padding: 0.75rem 1rem;
        border-radius: 999px;
        background: var(--ink);
        color: white;
      }

      .skip-link:focus {
        top: 0.75rem;
      }

      .shell {
        width: min(calc(100% - 2rem), var(--container));
        margin: 0 auto;
      }

      .topbar {
        border-bottom: 1px solid var(--line);
        background: rgba(255, 253, 249, 0.8);
        backdrop-filter: blur(14px);
      }

      .topbar__inner,
      .header__inner,
      .hero,
      .section,
      .footer__inner {
        display: grid;
        gap: 1.25rem;
      }

      .topbar__inner {
        grid-template-columns: 1fr auto;
        align-items: center;
        min-height: 2.75rem;
        font-size: 0.92rem;
        color: var(--muted);
      }

      .header {
        position: sticky;
        top: 0;
        z-index: 30;
        border-bottom: 1px solid var(--line);
        background: rgba(245, 241, 234, 0.86);
        backdrop-filter: blur(16px);
      }

      .header__inner {
        grid-template-columns: auto 1fr auto;
        align-items: center;
        min-height: 4.75rem;
      }

      .brand {
        display: inline-flex;
        align-items: center;
        gap: 0.75rem;
        font-weight: 700;
        letter-spacing: 0.03em;
      }

      .brand__mark {
        width: 2.2rem;
        height: 2.2rem;
        border-radius: 0.8rem;
        background:
          linear-gradient(145deg, var(--brand), #c97d4c);
        box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.35);
      }

      .nav {
        display: flex;
        justify-content: center;
        gap: 1.5rem;
        flex-wrap: wrap;
        color: var(--muted);
      }

      .nav a:focus-visible,
      .cta:focus-visible,
      .pill:focus-visible,
      .product-card:focus-within,
      .story-card:focus-within {
        outline: 3px solid rgba(157, 79, 43, 0.28);
        outline-offset: 3px;
        border-radius: 18px;
      }

      .header__actions {
        display: inline-flex;
        align-items: center;
        gap: 0.75rem;
      }

      .icon-btn,
      .cta,
      .pill {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        gap: 0.5rem;
        border: 0;
        border-radius: 999px;
        font: inherit;
        cursor: pointer;
        transition:
          transform 0.2s ease,
          box-shadow 0.2s ease,
          background 0.2s ease;
      }

      .icon-btn {
        width: 2.75rem;
        height: 2.75rem;
        background: rgba(255, 255, 255, 0.7);
        color: var(--ink);
        box-shadow: inset 0 0 0 1px var(--line);
      }

      .cta {
        padding: 0.95rem 1.35rem;
        font-weight: 600;
        color: white;
        background: linear-gradient(135deg, var(--brand), #cc7f51);
        box-shadow: 0 14px 25px rgba(157, 79, 43, 0.22);
      }

      .cta--ghost {
        color: var(--ink);
        background: rgba(255, 255, 255, 0.72);
        box-shadow: inset 0 0 0 1px var(--line);
      }

      .hero {
        grid-template-columns: 1.15fr 0.85fr;
        align-items: stretch;
        padding: 2rem 0 1.5rem;
