      .hero__copy,
      .hero__visual,
      .panel,
      .feature-strip,
      .product-card,
      .story-card,
      .deal-card {
        border: 1px solid var(--line);
        border-radius: var(--radius-xl);
        background: rgba(255, 253, 249, 0.84);
        box-shadow: var(--shadow);
      }

      .hero__copy {
        padding: clamp(1.5rem, 3vw, 3rem);
      }

      .eyebrow {
        display: inline-flex;
        align-items: center;
        gap: 0.5rem;
        padding: 0.45rem 0.85rem;
        border-radius: 999px;
        background: rgba(15, 118, 110, 0.1);
        color: var(--brand-2);
        font-size: 0.92rem;
        font-weight: 600;
      }

      .hero h1 {
        margin: 1rem 0 0.75rem;
        font-size: clamp(2.75rem, 6vw, 5.4rem);
        line-height: 0.96;
        letter-spacing: -0.05em;
      }

      .hero p {
        max-width: 38rem;
        margin: 0;
        color: var(--muted);
        font-size: 1.05rem;
      }

      .hero__actions {
        display: flex;
        flex-wrap: wrap;
        gap: 0.9rem;
        margin-top: 1.75rem;
      }

      .stats {
        display: grid;
        grid-template-columns: repeat(3, minmax(0, 1fr));
        gap: 0.75rem;
        margin-top: 2rem;
      }

      .stat {
        padding: 1rem;
        border-radius: 18px;
        background: rgba(243, 236, 226, 0.7);
      }

      .stat strong {
        display: block;
        font-size: 1.25rem;
      }

      .stat span {
        color: var(--muted);
        font-size: 0.93rem;
      }

      .hero__visual {
        overflow: hidden;
        min-height: 100%;
        padding: 1.1rem;
        display: grid;
        gap: 1rem;
        background:
          linear-gradient(145deg, rgba(255, 253, 249, 0.92), rgba(243, 236, 226, 0.92));
      }

      .visual-card {
        border-radius: 24px;
        padding: 1.2rem;
        background:
          linear-gradient(160deg, rgba(157, 79, 43, 0.96), rgba(217, 164, 69, 0.88));
        color: white;
        min-height: 20rem;
        display: grid;
        align-content: space-between;
        position: relative;
        overflow: hidden;
      }

      .visual-card::after {
        content: "";
        position: absolute;
        inset: auto -15% -22% auto;
        width: 14rem;
        height: 14rem;
        border-radius: 50%;
        background: rgba(255, 255, 255, 0.14);
      }

      .visual-card__badge {
        display: inline-flex;
        width: fit-content;
        padding: 0.4rem 0.75rem;
        border-radius: 999px;
        background: rgba(255, 255, 255, 0.16);
      }

      .visual-card__title {
        max-width: 13ch;
        margin: 0;
        font-size: clamp(2rem, 4vw, 3.25rem);
        line-height: 0.95;
      }

      .visual-grid {
        display: grid;
        grid-template-columns: 1fr 1fr;
        gap: 1rem;
      }

      .mini-card {
        padding: 1rem;
        border-radius: 22px;
        background: rgba(255, 255, 255, 0.8);
        display: grid;
        gap: 0.3rem;
        min-height: 9rem;
      }

      .mini-card strong {
        font-size: 1.3rem;
      }

      .section {
        padding: 1.4rem 0 2rem;
      }

      .section__head {
        display: flex;
        justify-content: space-between;
        align-items: end;
        gap: 1rem;
      }

      .section__head p {
        max-width: 50ch;
        margin: 0;
        color: var(--muted);
      }

      .section__head h2 {
        margin: 0.15rem 0 0;
        font-size: clamp(1.7rem, 3vw, 2.5rem);
        letter-spacing: -0.03em;
      }

      .chips {
        display: flex;
        gap: 0.6rem;
        flex-wrap: wrap;
      }

      .pill {
        padding: 0.7rem 1rem;
        background: rgba(255, 255, 255, 0.68);
        box-shadow: inset 0 0 0 1px var(--line);
        color: var(--muted);
      }

      .feature-strip {
        padding: 1rem;
        display: grid;
        grid-template-columns: repeat(4, minmax(0, 1fr));
        gap: 0.9rem;
      }

      .feature {
        padding: 1rem;
        border-radius: 18px;
        background: rgba(243, 236, 226, 0.7);
      }

      .feature strong {
        display: block;
        margin-bottom: 0.25rem;
      }

      .feature span {
        color: var(--muted);
        font-size: 0.95rem;
      }

      .products {
        display: grid;
        grid-template-columns: repeat(4, minmax(0, 1fr));
        gap: 1rem;
      }

      .product-card {
        overflow: hidden;
        padding: 0.9rem;
        display: grid;
        gap: 0.9rem;
      }

      .product-card__media {
        border-radius: 22px;
        min-height: 14rem;
        background:
          radial-gradient(circle at 35% 30%, rgba(255, 255, 255, 0.92), transparent 20%),
