        position: relative;
        overflow: hidden;
      }

      .product-card__media::before {
        content: "";
        position: absolute;
        inset: 18% 22% 14% 22%;
        border-radius: 34% 34% 28% 28%;
        background: rgba(255, 253, 249, 0.95);
        box-shadow: 0 20px 36px rgba(0, 0, 0, 0.15);
        transform: rotate(-7deg);
      }

      .product-card__meta,
      .story-card__body {
        padding: 0 0.2rem 0.2rem;
      }

      .product-card__title,
      .story-card h3 {
        margin: 0;
        font-size: 1.05rem;
      }

      .product-card__text,
      .story-card p,
      .deal-card p {
        margin: 0.35rem 0 0;
        color: var(--muted);
      }

      .product-card__footer {
        display: flex;
        justify-content: space-between;
        align-items: center;
        gap: 0.75rem;
        margin-top: 0.8rem;
      }

      .price {
        font-weight: 700;
        font-size: 1.05rem;
      }

      .product-card__actions {
        display: flex;
        gap: 0.6rem;
      }

      .deal-grid {
        display: grid;
        grid-template-columns: 1.15fr 0.85fr;
        gap: 1rem;
      }

      .deal-card {
        padding: clamp(1.2rem, 2.5vw, 2rem);
      }

      .deal-card--highlight {
        background:
          linear-gradient(135deg, rgba(15, 118, 110, 0.95), rgba(31, 26, 23, 0.92));
        color: white;
      }

      .deal-card--highlight p,
      .deal-card--highlight .meta {
        color: rgba(255, 255, 255, 0.82);
      }

      .deal-card__grid {
        display: grid;
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 0.9rem;
        margin-top: 1rem;
      }

      .deal-mini {
        padding: 1rem;
        border-radius: 18px;
        background: rgba(255, 255, 255, 0.1);
        border: 1px solid rgba(255, 255, 255, 0.14);
      }

      .deal-mini strong {
        display: block;
        font-size: 1.2rem;
        margin-bottom: 0.35rem;
      }

      .deal-mini span,
      .meta {
        font-size: 0.93rem;
      }

      .stories {
        display: grid;
        grid-template-columns: 1fr 1fr 1fr;
        gap: 1rem;
      }

      .story-card {
        overflow: hidden;
        display: grid;
      }

      .story-card__image {
        min-height: 12rem;
        background:
          linear-gradient(160deg, rgba(217, 164, 69, 0.9), rgba(157, 79, 43, 0.95)),
          #c98e63;
      }

      .story-card__image--calm {
        background:
          linear-gradient(160deg, rgba(15, 118, 110, 0.9), rgba(243, 236, 226, 0.9)),
          #7ab9b3;
      }

      .story-card__image--night {
        background:
          linear-gradient(160deg, rgba(31, 26, 23, 0.9), rgba(104, 82, 70, 0.95));
      }

      .story-card__body {
        padding-bottom: 1rem;
      }

      .footer {
        padding: 2rem 0 3rem;
      }

      .footer__inner {
        grid-template-columns: 1.25fr 0.75fr;
        padding-top: 1.75rem;
        border-top: 1px solid var(--line);
        color: var(--muted);
      }

      .footer__links {
        display: flex;
        gap: 1rem;
        flex-wrap: wrap;
        justify-content: end;
      }

      .tag {
        display: inline-flex;
        align-items: center;
        padding: 0.32rem 0.6rem;
        border-radius: 999px;
        background: rgba(255, 255, 255, 0.55);
        color: var(--muted);
        font-size: 0.86rem;
      }

      .sr-only {
        position: absolute;
        width: 1px;
        height: 1px;
        padding: 0;
        margin: -1px;
        overflow: hidden;
        clip: rect(0, 0, 0, 0);
        white-space: nowrap;
        border: 0;
      }

      @media (max-width: 960px) {
        .hero,
        .deal-grid,
        .footer__inner {
          grid-template-columns: 1fr;
        }

        .products,
        .stories,
        .feature-strip {
          grid-template-columns: repeat(2, minmax(0, 1fr));
        }

        .section__head,
        .header__inner {
          grid-template-columns: 1fr;
          justify-items: start;
        }

        .nav {
          justify-content: start;
        }

        .header__actions {
          justify-self: stretch;
        }

        .stats,
        .visual-grid,
        .deal-card__grid {
          grid-template-columns: 1fr 1fr;
        }
      }

      @media (max-width: 680px) {
        .shell {
          width: min(calc(100% - 1.2rem), var(--container));
        }

        .topbar__inner,
        .products,
        .stories,
        .feature-strip,
        .stats,
        .visual-grid,
        .deal-card__grid {
          grid-template-columns: 1fr;
        }

        .hero h1 {
          font-size: clamp(2.5rem, 14vw, 4rem);
        }

        .hero__actions,
        .header__actions,
        .footer__links {
          width: 100%;
        }

        .cta,
        .cta--ghost {
          width: 100%;
        }

        .nav {
          gap: 1rem;
          font-size: 0.95rem;
        }

        .visual-card {
          min-height: 16rem;
        }
      }
    </style>
  </head>
