              <div>
                <a class="brand" href="#" aria-label="Northstar Retail home">
                  <span class="brand__mark" aria-hidden="true"></span>
                  Northstar Retail
                </a>
                <p>
                  Elevated basics, considered design, and home goods made to feel calm and current.
                </p>
              </div>
              <div class="footer__links" aria-label="Footer links">
                <a href="#featured-products">Featured</a>
                <a href="#deals">Deals</a>
                <a href="#stories">Editorial</a>
              </div>
            </div>
          </footer>
        `;
      }

      function App() {
        return `
          ${TopBar()}
          ${Header()}
          <main id="main">
            ${Hero()}
            ${FeatureStrip()}
            ${FeaturedProducts()}
            ${Deals()}
            ${Stories()}
          </main>
          ${Footer()}
